document.addEventListener('DOMContentLoaded', () => {
  document.documentElement.classList.add('js');
  const navbar = document.querySelector('.navbar');
  const menuToggle = document.querySelector('.menu-toggle');
  const siteNav = document.querySelector('.site-nav');
  const languageToggle = document.querySelector('[data-language-toggle]');
  const sourceTexts = new WeakMap();
  const englishTitle = document.title;
  let language = 'en';
  let accountSignedIn = false;
  const getSavedLanguage = () => { try { return localStorage.getItem('biuret-language') === 'ar' ? 'ar' : 'en'; } catch { return 'en'; } };
  const saveLanguage = (value) => { try { localStorage.setItem('biuret-language', value); } catch {} };
  const scrollProgress = document.createElement('div');
  scrollProgress.className = 'scroll-progress';
  scrollProgress.setAttribute('aria-hidden', 'true');
  document.body.prepend(scrollProgress);
  const desktopAccountLink = document.querySelector('.account-btn');
  if (siteNav && desktopAccountLink && !siteNav.querySelector('[data-mobile-account-link]')) {
    const mobileAccountLink = document.createElement('a');
    mobileAccountLink.className = 'mobile-account-link';
    mobileAccountLink.href = desktopAccountLink.getAttribute('href') || 'auth.html';
    mobileAccountLink.dataset.mobileAccountLink = 'true';
    mobileAccountLink.textContent = 'Sign in';
    siteNav.append(mobileAccountLink);
  }
  const accountLinks = [...document.querySelectorAll('.account-btn, [data-mobile-account-link]')];
  const toAccountHref = (href) => String(href || 'auth.html').replace(/auth\.html(?=([?#]|$))/, 'account.html');
  const toAuthHref = (href) => String(href || 'auth.html').replace(/account\.html(?=([?#]|$))/, 'auth.html');
  const renderAccountLinks = () => accountLinks.forEach((link) => {
    const sourceHref = link.dataset.accountSourceHref || link.getAttribute('href') || 'auth.html';
    link.dataset.accountSourceHref = sourceHref;
    link.href = accountSignedIn ? toAccountHref(sourceHref) : toAuthHref(sourceHref);
    link.textContent = accountSignedIn ? (language === 'ar' ? 'الحساب' : 'Account') : (language === 'ar' ? 'تسجيل الدخول' : 'Sign in');
  });
  const syncAccountLinks = async () => {
    const service = window.BiuretAppwrite;
    if (!service?.configured) { renderAccountLinks(); return; }
    try { await service.getCurrentUser(); accountSignedIn = true; }
    catch { accountSignedIn = false; }
    renderAccountLinks();
  };
  const projectPage = document.querySelector('.project-page');
  if (projectPage) {
    const projectColor = getComputedStyle(projectPage).getPropertyValue('--project-color').trim();
    if (projectColor) document.documentElement.style.setProperty('--page-progress', projectColor);
  }
  const closeMenu = () => { navbar?.classList.remove('menu-open'); menuToggle?.setAttribute('aria-expanded', 'false'); };
  menuToggle?.addEventListener('click', () => { const isOpen = navbar?.classList.toggle('menu-open'); menuToggle.setAttribute('aria-expanded', String(Boolean(isOpen))); });
  siteNav?.querySelectorAll('a').forEach((link) => link.addEventListener('click', closeMenu));
  window.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeMenu(); });
  window.addEventListener('resize', () => { if (window.innerWidth > 720) closeMenu(); });
  document.querySelectorAll('a[href^="#"]').forEach((link) => link.addEventListener('click', (event) => {
    const target = document.querySelector(link.getAttribute('href'));
    if (!target) return;
    event.preventDefault();
    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }));
  const revealItems = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window) {
    const revealObserver = new IntersectionObserver((entries, observer) => entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add('visible'); observer.unobserve(entry.target); } }), { threshold: 0.1, rootMargin: '0px 0px -24px 0px' });
    revealItems.forEach((item) => revealObserver.observe(item));
  } else revealItems.forEach((item) => item.classList.add('visible'));
  const updateChrome = () => {
    navbar?.classList.toggle('scrolled', window.scrollY > 24);
    const scrollableHeight = document.documentElement.scrollHeight - window.innerHeight;
    scrollProgress.style.transform = `scaleX(${scrollableHeight > 0 ? Math.min(window.scrollY / scrollableHeight, 1) : 0})`;
  };
  updateChrome();
  window.addEventListener('scroll', updateChrome, { passive: true });
  const sections = [...document.querySelectorAll('main section[id]')];
  const navLinks = [...document.querySelectorAll('.site-nav a[href^="#"]')];
  if ('IntersectionObserver' in window && sections.length && navLinks.length) {
    const activeObserver = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) navLinks.forEach((link) => link.classList.toggle('active', link.getAttribute('href') === `#${entry.target.id}`)); }), { rootMargin: '-36% 0px -55% 0px' });
    sections.forEach((section) => activeObserver.observe(section));
  }
  const cards = [...document.querySelectorAll('.project-card[data-category]')];
  const filters = [...document.querySelectorAll('.filter-button[data-filter]')];
  const projectCount = document.querySelector('[data-project-count]');
  const renderProjectCount = (shown) => {
    if (projectCount) projectCount.textContent = language === 'ar' ? `عرض ${shown} ${shown === 1 ? 'مشروع' : 'مشاريع'}` : `${shown} ${shown === 1 ? 'project' : 'projects'} shown`;
  };
  filters.forEach((button) => button.addEventListener('click', () => {
    const filter = button.dataset.filter;
    let shown = 0;
    cards.forEach((card) => { const matches = filter === 'all' || card.dataset.category.split(' ').includes(filter); card.hidden = !matches; if (matches) shown += 1; });
    filters.forEach((item) => item.setAttribute('aria-pressed', String(item === button)));
    renderProjectCount(shown);
  }));
  const translateTextNodes = () => {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, { acceptNode: (node) => node.parentElement?.closest('script, style, [data-language-toggle]') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT });
    const textNodes = [];
    while (walker.nextNode()) textNodes.push(walker.currentNode);
    textNodes.forEach((node) => {
      const source = sourceTexts.get(node) ?? node.nodeValue;
      sourceTexts.set(node, source);
      if (language === 'en') { node.nodeValue = source; return; }
      const match = source.match(/^(\s*)([\s\S]*?)(\s*)$/);
      const translated = arabicTranslations[match[2]];
      node.nodeValue = translated ? `${match[1]}${translated}${match[3]}` : source;
    });
  };
  const applyLanguage = (nextLanguage) => {
    language = nextLanguage;
    const isArabic = language === 'ar';
    document.documentElement.lang = isArabic ? 'ar' : 'en';
    document.documentElement.dir = isArabic ? 'rtl' : 'ltr';
    document.body.classList.toggle('is-arabic', isArabic);
    translateTextNodes();
    languageToggle?.setAttribute('aria-pressed', String(isArabic));
    languageToggle?.setAttribute('aria-label', isArabic ? 'Switch language to English' : 'Switch language to Arabic');
    const languageCode = languageToggle?.querySelector('.language-code');
    const languageKicker = languageToggle?.querySelector('.language-kicker');
    const languageLabel = languageToggle?.querySelector('.language-label');
    if (languageCode) languageCode.textContent = isArabic ? 'EN' : 'ع';
    if (languageKicker) languageKicker.textContent = isArabic ? 'اللغة' : 'Language';
    if (languageLabel) languageLabel.textContent = isArabic ? 'English' : 'العربية';
    if (menuToggle) menuToggle.setAttribute('aria-label', isArabic ? 'تبديل التنقل' : 'Toggle navigation');
    if (siteNav) siteNav.setAttribute('aria-label', isArabic ? 'التنقل الرئيسي' : 'Primary navigation');
    const filename = window.location.pathname.split('/').pop() || 'index.html';
    document.title = isArabic ? (arabicTitles[filename] || englishTitle) : englishTitle;
    renderProjectCount(cards.filter((card) => !card.hidden).length);
    renderAccountLinks();
  };
  const authForm = document.querySelector('[data-auth-form]');
  const authTabs = [...document.querySelectorAll('[data-auth-mode]')];
  const authHeading = document.querySelector('[data-auth-heading]');
  const authDescription = document.querySelector('[data-auth-description]');
  const authConfirm = document.querySelector('[data-auth-confirm]');
  const authSubmit = document.querySelector('[data-auth-submit]');
  const authSwitchCopy = document.querySelector('[data-auth-switch-copy]');
  const authSwitch = document.querySelector('[data-auth-switch]');
  const authNotice = document.querySelector('[data-auth-notice]');
  let authMode = 'signin';
  const authCopy = {
    signin: {
      en: { heading: 'Welcome back.', description: 'Access your profile and keep your account secure.', submit: 'Sign in', switchCopy: 'New to Biuret?', switchAction: 'Create account' },
      ar: { heading: 'مرحباً بعودتك.', description: 'ادخل إلى ملفك الشخصي وحافظ على أمان حسابك.', submit: 'تسجيل الدخول', switchCopy: 'جديد في بيوريت؟', switchAction: 'إنشاء حساب' }
    },
    signup: {
      en: { heading: 'Set up your account.', description: 'Create a secure profile for portfolio updates and future member features.', submit: 'Create account', switchCopy: 'Already have an account?', switchAction: 'Sign in' },
      ar: { heading: 'أنشئ حسابك.', description: 'أنشئ ملفاً آمناً لتحديثات معرض الأعمال وميزات الأعضاء المستقبلية.', submit: 'إنشاء حساب', switchCopy: 'لديك حساب بالفعل؟', switchAction: 'تسجيل الدخول' }
    }
  };
  function syncAuthMode() {
    if (!authForm) return;
    const copy = authCopy[authMode][language];
    authTabs.forEach((tab) => { const active = tab.dataset.authMode === authMode; tab.classList.toggle('is-active', active); tab.setAttribute('aria-selected', String(active)); });
    if (authHeading) authHeading.textContent = copy.heading;
    if (authDescription) authDescription.textContent = copy.description;
    if (authSubmit) authSubmit.textContent = copy.submit;
    if (authSwitchCopy) authSwitchCopy.textContent = copy.switchCopy;
    if (authSwitch) authSwitch.textContent = copy.switchAction;
    if (authConfirm) { authConfirm.hidden = authMode !== 'signup'; authConfirm.querySelector('input')?.toggleAttribute('required', authMode === 'signup'); }
    const password = authForm.querySelector('[name="password"]');
    if (password) password.autocomplete = authMode === 'signup' ? 'new-password' : 'current-password';
    if (authNotice) authNotice.textContent = '';
  }
  authTabs.forEach((tab) => tab.addEventListener('click', () => { authMode = tab.dataset.authMode === 'signup' ? 'signup' : 'signin'; syncAuthMode(); }));
  authSwitch?.addEventListener('click', () => { authMode = authMode === 'signin' ? 'signup' : 'signin'; syncAuthMode(); });
  const getSafeAccountRedirect = () => {
    const target = new URLSearchParams(window.location.search).get('redirect');
    return target && /^account\.html(?:[?#]|$)/.test(target) ? target : 'account.html';
  };
  const authErrorCopy = (error) => {
    const code = Number(error?.code || error?.status || error?.response?.status || 0);
    const type = String(error?.type || error?.response?.data?.type || '').toLowerCase();
    if (code === 429 || type.includes('rate_limit')) {
      return language === 'ar'
        ? 'تم إيقاف محاولات تسجيل الدخول مؤقتًا لحماية الحساب. انتظر قليلًا ثم حاول مرة واحدة فقط.'
        : 'Sign-in attempts are temporarily limited to protect the account. Wait a little, then try once.';
    }
    if (code === 401 || type.includes('invalid_credentials')) {
      return language === 'ar' ? 'البريد الإلكتروني أو كلمة المرور غير صحيحة.' : 'The email or password is incorrect.';
    }
    if (code === 403 || type.includes('email_not_verified')) {
      return language === 'ar'
        ? 'تحقق من بريدك الإلكتروني أولًا، ثم حاول تسجيل الدخول.'
        : 'Verify your email first, then try signing in.';
    }
    if (type.includes('project') || type.includes('platform')) {
      return language === 'ar'
        ? 'إعداد اتصال الموقع بالحسابات غير مكتمل. أعد تحميل الصفحة ثم حاول مرة أخرى.'
        : 'The site-to-account connection is not configured correctly. Reload the page and try again.';
    }
    return language === 'ar'
      ? 'تعذر إكمال تسجيل الدخول الآن. أعد تحميل الصفحة ثم حاول مرة واحدة.'
      : 'Sign-in could not be completed right now. Reload the page, then try once.';
  };
  authForm?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const service = window.BiuretAppwrite;
    if (!service?.configured) {
      if (authNotice) authNotice.textContent = language === 'ar' ? 'أكمل إعداد Appwrite أولاً لتفعيل الحسابات الحقيقية.' : 'Complete the Appwrite setup first to activate real accounts.';
      return;
    }
    if (authMode === 'signup') {
      const password = authForm.querySelector('[name="password"]')?.value;
      const confirmation = authForm.querySelector('[name="password-confirm"]')?.value;
      if (password !== confirmation) { if (authNotice) authNotice.textContent = language === 'ar' ? 'كلمتا المرور غير متطابقتين.' : 'Passwords do not match.'; return; }
    }
    const email = authForm.querySelector('[name="email"]')?.value.trim();
    const password = authForm.querySelector('[name="password"]')?.value;
    if (!email || !password) return;
    if (authSubmit) authSubmit.disabled = true;
    if (authNotice) authNotice.textContent = language === 'ar' ? 'جارٍ التحقق بأمان…' : 'Checking securely…';
    try {
      if (authMode === 'signup') await service.signUp({ email, password });
      else await service.signIn({ email, password });
      window.location.assign(getSafeAccountRedirect());
    } catch (error) {
      if (authNotice) authNotice.textContent = authErrorCopy(error);
      if (authSubmit) authSubmit.disabled = false;
    }
  });
  if (authForm && window.BiuretAppwrite?.configured) {
    window.BiuretAppwrite.getCurrentUser().then(() => window.location.replace(getSafeAccountRedirect())).catch(() => {});
  }

  const licenseProducts = {
    academy: { name: 'Biuret Academy', accent: 'EDUCATION · ARABIC LEARNING', subject: 'Biuret Academy license inquiry', en: 'An Arabic cybersecurity learning platform designed for a focused and accessible student experience.', ar: 'منصّة عربية لتعلّم الأمن السيبراني، مصمّمة لتجربة طالب مركّزة وسهلة الوصول.' },
    biulock: { name: 'BiuLock', accent: 'SECURITY · LOCAL PROTECTION', subject: 'BiuLock license inquiry', prices: { monthly: '$9.99' }, en: 'A local-first security tool for carefully protected credentials and personal data.', ar: 'أداة أمان محلية أولاً لحماية بيانات الدخول والبيانات الشخصية بعناية.' },
    brecon: { name: 'B-Recon', accent: 'RESEARCH · OSINT', subject: 'B-Recon license inquiry', en: 'A structured workspace for authorized research, cases, evidence, and clear reporting.', ar: 'مساحة عمل منظّمة للبحث المصرّح به والقضايا والأدلة والتقارير الواضحة.' },
    biusniff: { name: 'BiuSniff', accent: 'NETWORK · INSPECTION', subject: 'BiuSniff license inquiry', en: 'A focused network inspection experience for authorized learning and analysis.', ar: 'تجربة مركّزة لفحص الشبكات للتعلّم والتحليل المصرّح بهما.' },
    biucrypt: { name: 'BiuCrypt', accent: 'CRYPTOGRAPHY · FILE PROTECTION', subject: 'BiuCrypt license inquiry', en: 'A practical encryption suite for more deliberate file and folder protection.', ar: 'حزمة تشفير عملية لحماية أكثر وعياً للملفات والمجلدات.' },
    reaper: { name: 'Biuret Reaper', accent: 'SECURITY · NETWORK TOOLING', subject: 'Biuret Reaper license inquiry', en: 'A purpose-built network visibility tool for authorized environments.', ar: 'أداة مخصّصة لرؤية الشبكات في البيئات المصرّح بها.' }
  };
  const licenseButtons = [...document.querySelectorAll('.license-product[data-product]')];
  const licensePlanButtons = [...document.querySelectorAll('[data-license-plan]')];
  const licenseName = document.querySelector('[data-license-name]');
  const licenseDescription = document.querySelector('[data-license-description]');
  const licenseAccent = document.querySelector('[data-license-accent]');
  const licenseCheckout = document.querySelector('[data-license-checkout]');
  const licenseCheckoutLabel = document.querySelector('[data-license-checkout-label]');
  const licenseCheckoutStatus = document.querySelector('[data-license-checkout-status]');
  const licenseAvailabilityCells = [...document.querySelectorAll('[data-license-availability]')];
  const checkoutPrices = window.BIURET_PADDLE_CONFIG?.prices || {};
  const planKeys = ['monthly', 'threeMonths', 'yearly'];
  const priceIsConfigured = (productSlug, plan) => /^pri_[a-z\d]{26}$/i.test(String(checkoutPrices[productSlug]?.[plan] || ''));
  const initialProduct = new URLSearchParams(window.location.search).get('product');
  const initialPlan = new URLSearchParams(window.location.search).get('plan');
  let selectedProduct = licenseProducts[initialProduct] ? initialProduct : 'biulock';
  let selectedPlan = planKeys.includes(initialPlan) ? initialPlan : 'monthly';
  function syncLicenseSelection() {
    const product = licenseProducts[selectedProduct];
    if (!product || !licenseName) return;
    const availablePlans = planKeys.filter((plan) => priceIsConfigured(selectedProduct, plan));
    if (!priceIsConfigured(selectedProduct, selectedPlan)) selectedPlan = availablePlans[0] || 'monthly';
    const checkoutAvailable = priceIsConfigured(selectedProduct, selectedPlan);
    licenseName.textContent = product.name;
    if (licenseDescription) licenseDescription.textContent = product[language];
    if (licenseAccent) licenseAccent.textContent = product.accent;
    if (licenseCheckout) {
      licenseCheckout.dataset.product = selectedProduct;
      licenseCheckout.dataset.plan = selectedPlan;
      licenseCheckout.disabled = !checkoutAvailable;
    }
    if (licenseCheckoutLabel) {
      licenseCheckoutLabel.textContent = checkoutAvailable
        ? (language === 'ar' ? `شراء ${product.name}` : `Buy ${product.name}`)
        : (language === 'ar' ? 'قريبًا' : 'Coming soon');
    }
    if (licenseCheckoutStatus) {
      licenseCheckoutStatus.textContent = checkoutAvailable
        ? (language === 'ar' ? 'هذه الخطة متاحة حاليًا عبر Paddle Sandbox.' : 'This plan is currently available through Paddle Sandbox.')
        : (language === 'ar' ? 'هذا المنتج أو الخطة غير متاح للشراء بعد.' : 'This product or plan is not available for purchase yet.');
      licenseCheckoutStatus.dataset.status = 'neutral';
    }
    licenseAvailabilityCells.forEach((cell) => {
      const plan = cell.dataset.licenseAvailability;
      const available = priceIsConfigured(selectedProduct, plan);
      const displayPrice = product.prices?.[plan];
      cell.textContent = available
        ? `${product.name} · ${displayPrice || (language === 'ar' ? 'متاح' : 'Available')}`
        : (language === 'ar' ? 'قريبًا' : 'Coming soon');
    });
    licenseButtons.forEach((button) => {
      const selected = button.dataset.product === selectedProduct;
      const productAvailable = planKeys.some((plan) => priceIsConfigured(button.dataset.product, plan));
      button.classList.toggle('is-selected', selected);
      button.classList.toggle('is-coming-soon', !productAvailable);
      button.setAttribute('aria-pressed', String(selected));
      if (button.lastElementChild) button.lastElementChild.textContent = productAvailable ? '→' : (language === 'ar' ? 'قريبًا' : 'Soon');
    });
    licensePlanButtons.forEach((button) => {
      const available = priceIsConfigured(selectedProduct, button.dataset.licensePlan);
      const selected = button.dataset.licensePlan === selectedPlan;
      button.disabled = !available;
      button.classList.toggle('is-selected', selected);
      button.setAttribute('aria-pressed', String(selected));
      const availability = button.querySelector('strong');
      if (availability) {
        availability.textContent = available
          ? (product.prices?.[button.dataset.licensePlan] || (language === 'ar' ? 'متاح' : 'Available'))
          : (language === 'ar' ? 'قريبًا' : 'Coming soon');
      }
    });
  }
  licenseButtons.forEach((button) => button.addEventListener('click', () => { selectedProduct = button.dataset.product; selectedPlan = 'monthly'; syncLicenseSelection(); }));
  licensePlanButtons.forEach((button) => button.addEventListener('click', () => { selectedPlan = button.dataset.licensePlan; syncLicenseSelection(); }));
  languageToggle?.addEventListener('click', () => { const nextLanguage = language === 'en' ? 'ar' : 'en'; saveLanguage(nextLanguage); applyLanguage(nextLanguage); syncAuthMode(); syncLicenseSelection(); });
  applyLanguage(getSavedLanguage());
  syncAccountLinks();
  syncAuthMode();
  syncLicenseSelection();
});
